// --- Recurring todos (added as separate functions; existing API untouched) ---
export const RECURRENCES = ["daily", "weekly", "monthly"];

// Next due date (ISO string) after `due` for a recurrence. Monthly dates are
// clamped to the month's last day; `day` is the anchor day-of-month so that
// Jan 31 -> Feb 28 -> Mar 31 rather than drifting to the 28th.
export function nextDue(due, repeat, day) {
  if (!RECURRENCES.includes(repeat)) throw new Error(`invalid recurrence: ${repeat}`);
  const d = new Date(due);
  if (Number.isNaN(d.getTime())) throw new Error("invalid due date");
  if (repeat === "daily") d.setUTCDate(d.getUTCDate() + 1);
  else if (repeat === "weekly") d.setUTCDate(d.getUTCDate() + 7);
  else {
    const anchor = day ?? d.getUTCDate();
    d.setUTCDate(1);
    d.setUTCMonth(d.getUTCMonth() + 1);
    const last = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
    d.setUTCDate(Math.min(anchor, last));
  }
  return d.toISOString();
}

// Add a recurring todo. `repeat` is one of RECURRENCES; `due` defaults to now.
TodoList.prototype.addRecurring = function (title, repeat, { due = new Date(), priority } = {}) {
  if (!RECURRENCES.includes(repeat)) throw new Error(`invalid recurrence: ${repeat}`);
  const item = this.add(title, { due, priority });
  item.repeat = repeat;
  item.repeatDay = new Date(item.due).getUTCDate();
  return item;
};

// Complete an item; if it recurs, schedule the next occurrence.
// Returns { item, next } where next is null for non-recurring items.
TodoList.prototype.completeAndReschedule = function (id) {
  const found = this.items.find(i => i.id === id);
  if (!found) throw new Error(`item ${id} not found`);
  const wasDone = found.done;
  const item = this.complete(id);
  if (wasDone || !item.repeat) return { item, next: null };
  const next = this.add(item.title, { due: nextDue(item.due, item.repeat, item.repeatDay), priority: item.priority });
  next.repeat = item.repeat;
  next.repeatDay = item.repeatDay;
  return { item, next };
};
