import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { TodoList, nextDue } from "../src/todo.js";

test("daily and weekly advance by fixed days", () => {
  assert.equal(nextDue("2026-01-31T09:00:00.000Z", "daily"), "2026-02-01T09:00:00.000Z");
  assert.equal(nextDue("2026-12-28T09:00:00.000Z", "weekly"), "2027-01-04T09:00:00.000Z");
});

test("monthly clamps to month end and keeps the anchor day", () => {
  assert.equal(nextDue("2026-01-31T00:00:00.000Z", "monthly", 31), "2026-02-28T00:00:00.000Z");
  assert.equal(nextDue("2026-02-28T00:00:00.000Z", "monthly", 31), "2026-03-31T00:00:00.000Z");
  assert.equal(nextDue("2028-01-31T00:00:00.000Z", "monthly"), "2028-02-29T00:00:00.000Z");
  assert.equal(nextDue("2026-12-15T00:00:00.000Z", "monthly"), "2027-01-15T00:00:00.000Z");
});

test("invalid recurrence throws", () => {
  const list = new TodoList();
  assert.throws(() => list.addRecurring("x", "hourly"), /invalid recurrence/);
  assert.throws(() => nextDue("2026-01-01", "yearly"), /invalid recurrence/);
});

test("completing a recurring todo schedules the next one", () => {
  const list = new TodoList();
  const a = list.addRecurring("water plants", "weekly", { due: "2026-03-01T08:00:00Z", priority: "high" });
  const { item, next } = list.completeAndReschedule(a.id);
  assert.equal(item.done, true);
  assert.equal(next.done, false);
  assert.equal(next.title, "water plants");
  assert.equal(next.priority, "high");
  assert.equal(next.repeat, "weekly");
  assert.equal(next.due, "2026-03-08T08:00:00.000Z");
  assert.deepEqual(list.pending().map(i => i.id), [next.id]);
});

test("monthly chain from Jan 31 survives February", () => {
  const list = new TodoList();
  let t = list.addRecurring("rent", "monthly", { due: "2026-01-31T00:00:00Z" });
  t = list.completeAndReschedule(t.id).next;
  assert.equal(t.due, "2026-02-28T00:00:00.000Z");
  t = list.completeAndReschedule(t.id).next;
  assert.equal(t.due, "2026-03-31T00:00:00.000Z");
});

test("non-recurring completes without a next; double-complete does not duplicate", () => {
  const list = new TodoList();
  const a = list.add("once");
  assert.equal(list.completeAndReschedule(a.id).next, null);
  const r = list.addRecurring("daily thing", "daily");
  list.completeAndReschedule(r.id);
  assert.equal(list.completeAndReschedule(r.id).next, null);
  assert.equal(list.items.length, 3);
  assert.throws(() => list.completeAndReschedule(99), /not found/);
});

test("recurrence survives save/load", () => {
  const dir = mkdtempSync(join(tmpdir(), "todo-"));
  try {
    const p = join(dir, "t.json");
    const list = new TodoList();
    list.addRecurring("rent", "monthly", { due: "2026-01-31T00:00:00Z" });
    list.save(p);
    const back = TodoList.load(p);
    assert.equal(back.completeAndReschedule(1).next.due, "2026-02-28T00:00:00.000Z");
  } finally { rmSync(dir, { recursive: true, force: true }); }
});
